import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

_SYMBOLS = {
    "$": "USD",
    "€": "EUR",
    "£": "GBP",
    "¥": "JPY",
    "₹": "INR",
}

_SKIP_ORDER_WORDS = {
    "number",
    "no",
    "ref",
    "reference",
    "id",
    "invoice",
    "order",
    "total",
    "amount",
    "due",
    "balance",
}

_AMOUNT_CORE = r"[-+]?\s*[€£$¥₹]?\s*[-+]?\s*\d(?:[\d.,]*\d)?"


def _normalize_amount(raw):
    if raw is None:
        return None

    s = raw.strip()
    if not s:
        return None

    for sym in _SYMBOLS:
        s = s.replace(sym, "")

    s = s.replace(" ", "").replace("\u00a0", "")
    if not s:
        return None

    sign = ""
    if s[0] in "+-":
        sign = s[0]
        s = s[1:]

    if not s:
        return None

    if s.startswith("."):
        s = "0" + s
    if s.startswith(","):
        s = "0" + s
    if s.endswith("."):
        s = s[:-1]
    if s.endswith(","):
        s = s[:-1]

    if not s:
        return None

    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        if re.fullmatch(r"\d{1,3}(?:,\d{3})+", s):
            s = s.replace(",", "")
        elif re.fullmatch(r"\d+(?:,\d{3})*,\d{1,2}", s):
            last = s.rfind(",")
            s = s[:last].replace(",", "") + "." + s[last + 1:]
        elif re.fullmatch(r"\d+,\d{1,2}", s):
            s = s.replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "." in s:
        if s.count(".") > 1:
            parts = s.split(".")
            if all(len(p) == 3 for p in parts[1:]):
                s = "".join(parts)
            else:
                s = ".".join(parts[:-1]) + "." + parts[-1]

    try:
        d = Decimal(s)
    except InvalidOperation:
        return None

    try:
        q = d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except InvalidOperation:
        return None

    if sign == "-" and q != 0:
        return "-" + str(q)
    return str(q)


def _currency_from_amount(raw, text, start, end):
    if raw:
        for sym, cur in _SYMBOLS.items():
            if sym in raw:
                return cur

    after = text[end:end + 12]
    for sym, cur in _SYMBOLS.items():
        if sym in after:
            return cur

    m = re.search(r"\b([A-Z]{3})\b", after)
    if m:
        return m.group(1).upper()

    before = text[max(0, start - 12):start]
    for sym, cur in _SYMBOLS.items():
        if sym in before:
            return cur

    m = re.search(r"\b([A-Z]{3})\b", before)
    if m:
        return m.group(1).upper()

    return None


def extract(text: str) -> dict:
    if not isinstance(text, str):
        text = "" if text is None else str(text)

    order_no = None
    order_patterns = [
        r"(?i)\bfor\s+order\s+(?:no\.?|number|#)?\s*[:\-]?\s*([A-Z0-9][A-Z0-9_-]*)",
        r"(?i)\border\s+(?:no\.?|number|#)\s*[:\-]?\s*([A-Z0-9][A-Z0-9_-]*)",
        r"(?i)\border\s*[:\-]\s*([A-Z0-9][A-Z0-9_-]*)",
        r"(?i)\border\s+([A-Z0-9][A-Z0-9_-]*)",
    ]

    for pat in order_patterns:
        for m in re.finditer(pat, text):
            val = m.group(1)
            if val.lower() in _SKIP_ORDER_WORDS:
                continue
            order_no = val
            break
        if order_no:
            break

    amount = None
    currency = None

    total_patterns = [
        r"(?i)\btotal\b\s*[:\-]?\s*(?P<currency1>[A-Z]{3})?\s*(?P<amount>" + _AMOUNT_CORE + r")\s*(?P<currency2>[A-Z]{3})?",
        r"(?i)\b(?:amount due|balance due|amount|due)\b\s*[:\-]?\s*(?P<currency1>[A-Z]{3})?\s*(?P<amount>" + _AMOUNT_CORE + r")\s*(?P<currency2>[A-Z]{3})?",
    ]

    for pat in total_patterns:
        m = re.search(pat, text)
        if not m:
            continue

        raw = m.group("amount")
        amt = _normalize_amount(raw)
        if not amt:
            continue

        amount = amt
        cur = m.group("currency2") or m.group("currency1")
        if not cur:
            cur = _currency_from_amount(raw, text, m.start("amount"), m.end("amount"))
        if cur:
            currency = cur.upper()
        break

    if amount is None:
        fallback_pat = (
            r"(?<![A-Z0-9_-])(?P<currency1>[A-Z]{3})?\s*(?P<amount>" + _AMOUNT_CORE + r")\s*(?P<currency2>[A-Z]{3})?(?![A-Z0-9_-])"
        )
        candidates = []
        order_amount = _normalize_amount(order_no) if order_no else None

        for m in re.finditer(fallback_pat, text):
            raw = m.group("amount")
            amt = _normalize_amount(raw)
            if not amt:
                continue

            if order_no and (raw in order_no or (order_amount and amt == order_amount)):
                continue

            cur = m.group("currency2") or m.group("currency1")
            if not cur:
                cur = _currency_from_amount(raw, text, m.start("amount"), m.end("amount"))

            has_currency = bool(cur)
            has_decimal = ("." in raw or "," in raw)
            candidates.append((m.start(), raw, amt, cur, has_currency, has_decimal))

        if candidates:
            preferred = [c for c in candidates if c[4] or c[5]]
            if preferred:
                chosen = sorted(
                    preferred,
                    key=lambda x: (0 if x[4] else 1, 0 if x[5] else 1, x[0])
                )[0]
            else:
                chosen = sorted(candidates, key=lambda x: x[0])[0]

            amount = chosen[2]
            if chosen[3]:
                currency = chosen[3].upper()

    return {
        "order_no": order_no,
        "amount": amount,
        "currency": currency,
    }
